gzj(){return"\u092c\u093e\u0924\u091a\u0940\u0924 \u0915\u0940 \u092f\u093e\u0926"},
gBM(){return"\u0907\u0938 \u091a\u0948\u091f \u0915\u0947 \u0932\u093f\u090f \u0936\u0948\u0932\u0940 \u0938\u0947\u0935 \u0915\u0930\u0947\u0902"},
gJU(){return"\u0907\u0938 \u091a\u0948\u091f \u0915\u0940 \u0936\u0948\u0932\u0940 \u092c\u0926\u0932\u0947\u0902"},
